package com.mygo.music;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.*;
import android.media.projection.*;
import android.os.*;

/** Captures only this UID's media output. No microphone, audio files, or display capture is created. */
public final class PlayerAudioCaptureService extends Service {
    private static volatile PlayerAudioCaptureService live;private volatile boolean closed;private final Object gate=new Object();
    private MediaProjection projection;private AudioRecord recorder;private Thread worker;
    static void changed(){PlayerAudioCaptureService instance=live;if(instance!=null){synchronized(instance.gate){instance.gate.notifyAll();}if(!instance.wanted()){AudioRecord r=instance.recorder;if(r!=null)try{r.stop();}catch(Exception ignored){}AudioAnalysis.clear(AudioAnalysis.remote?"远程设备没有本机音频数据":"音频分析已就绪，等待播放");}}}
    private boolean wanted(){return !closed&&AudioAnalysis.visible&&AudioAnalysis.playing&&!AudioAnalysis.remote;}
    @Override public IBinder onBind(Intent intent){return null;}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null||"stop".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(projection!=null)return START_NOT_STICKY;
        try{if(Build.VERSION.SDK_INT<29)throw new IllegalStateException("需要 Android 10");NotificationManager notifications=getSystemService(NotificationManager.class);notifications.createNotificationChannel(new NotificationChannel("mygo-analysis","本应用音频分析",NotificationManager.IMPORTANCE_LOW));Intent stop=new Intent(this,PlayerAudioCaptureService.class).setAction("stop");PendingIntent pending=PendingIntent.getService(this,3081,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(this,"mygo-analysis").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("MyGo Music 音频分析").setContentText("仅分析本应用输出，点击停止").setContentIntent(pending).addAction(new Notification.Action.Builder(null,"停止",pending).build()).setOngoing(true).build();startForeground(3081,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);MediaProjectionManager manager=getSystemService(MediaProjectionManager.class);Intent grant=intent.getParcelableExtra("data");projection=manager.getMediaProjection(intent.getIntExtra("result",Activity.RESULT_CANCELED),grant);projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},new Handler(Looper.getMainLooper()));AudioPlaybackCaptureConfiguration config=new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUid(android.os.Process.myUid()).addMatchingUsage(AudioAttributes.USAGE_MEDIA).build();int size=Math.max(16384,AudioRecord.getMinBufferSize(48000,AudioFormat.CHANNEL_IN_STEREO,AudioFormat.ENCODING_PCM_16BIT)*4);recorder=new AudioRecord.Builder().setAudioPlaybackCaptureConfig(config).setAudioFormat(new AudioFormat.Builder().setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_IN_STEREO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(size).build();if(recorder.getState()!=AudioRecord.STATE_INITIALIZED)throw new IllegalStateException("设备无法创建双声道分析通道");live=this;AudioAnalysis.authorized=true;AudioAnalysis.clear("音频分析已就绪，等待播放");worker=new Thread(this::capture,"mygo-output-analysis");worker.start();}catch(Exception error){AudioAnalysis.clear("音频分析不可用："+error.getMessage());stopSelf();}return START_NOT_STICKY;}
    private void capture(){AudioSpectrumMath fft=new AudioSpectrumMath();short[] samples=new short[4096];try{while(!closed){synchronized(gate){while(!closed&&!wanted())gate.wait();}if(closed)break;fft.reset();recorder.startRecording();while(wanted()){int count=recorder.read(samples,0,samples.length,AudioRecord.READ_BLOCKING);if(count<0){if(wanted())throw new IllegalStateException("读取音频失败 "+count);break;}AudioAnalysis.Frame frame=fft.append(samples,count,48000);if(frame!=null&&wanted())AudioAnalysis.measured=frame;}try{recorder.stop();}catch(Exception ignored){}}}catch(InterruptedException ignored){}catch(Exception error){AudioAnalysis.clear("音频分析已停止："+error.getMessage());new Handler(Looper.getMainLooper()).post(this::stopSelf);}}
    @Override public void onDestroy(){closed=true;if(live==this)live=null;AudioAnalysis.authorized=false;AudioAnalysis.clear("音频分析已关闭");synchronized(gate){gate.notifyAll();}if(recorder!=null)try{recorder.stop();}catch(Exception ignored){}if(worker!=null)worker.interrupt();final AudioRecord old=recorder;recorder=null;if(old!=null)new Thread(()->{try{if(worker!=null)worker.join(800);}catch(InterruptedException ignored){}old.release();},"mygo-analysis-release").start();if(projection!=null){projection.stop();projection=null;}stopForeground(true);super.onDestroy();}
}
